import{_ as t,a as o}from"./chunks/on-course-dialog.DTINzmch.js";import{_ as n}from"./chunks/info-pending-downloads.DZEQoJ1v.js";import{c as s,Q as a,j as r,m as i}from"./chunks/framework.BqPkuuVc.js";const h="/assets/pending-dialog.DZpNKhgh.png",l="/assets/competitors-on-course-filter.T2vsgvAW.png",c="/assets/classes-on-course-column._Jd53DCu.png",d="/assets/spectator-class-list-on-course.DN0TsJE1.png",T=JSON.parse('{"title":"Seeing who is still on course","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/who-is-still-on-course.md","filePath":"user/running-the-event/who-is-still-on-course.md"}'),u={name:"user/running-the-event/who-is-still-on-course.md"};function g(m,e,p,w,y,f){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="seeing-who-is-still-on-course" tabindex="-1">Seeing who is still on course <a class="header-anchor" href="#seeing-who-is-still-on-course" aria-label="Permalink to &quot;Seeing who is still on course&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators, organisers and commentators who need to know who is still out — whether that is for safety, for the download tent, or for the commentary box.</p><p><em>Who is still out there?</em> gets asked all day, by different people, for different reasons: the start team wants to know the field is flowing, the commentator wants to know who is about to come in, and at the end of the day somebody has to be able to say nobody is left in the forest. Manager answers it in several places, each shaped for one of those jobs.</p><p>This page is the map of <strong>where to look</strong>. The end-of-day procedure — how to work the list down to zero and what to do with each name — is <a href="./safety-check">Safety check: accounting for everyone</a>.</p><blockquote><p>Manager says <strong>On course</strong> in the UI where other systems may say <em>In forest</em>. They mean the same thing.</p></blockquote><h2 id="pick-the-one-that-fits-the-question" tabindex="-1">Pick the one that fits the question <a class="header-anchor" href="#pick-the-one-that-fits-the-question" aria-label="Permalink to &quot;Pick the one that fits the question&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Look at</th></tr></thead><tbody><tr><td>See at a glance how many are still out</td><td><a href="#the-dashboard-competitors-tile">The dashboard Competitors tile</a></td></tr><tr><td>Work through every name still out</td><td><a href="#the-on-course-dialog">The On course dialog</a></td></tr><tr><td>Chase the runners who finished but haven&#39;t downloaded</td><td><a href="#the-pending-dialog">The Pending dialog</a>, <a href="#the-pending-downloads-tile">the Pending downloads tile</a>, or <a href="#the-pending-downloads-info-screen">the Pending downloads screen</a></td></tr><tr><td>Work through the people who never went out</td><td><a href="#the-not-started-dialog">The Not started dialog</a></td></tr><tr><td>Search, sort or edit the people still out</td><td><a href="#the-competitor-list">The competitor list</a></td></tr><tr><td>Know which courses still have people on them</td><td><a href="#the-class-list">The class list</a></td></tr><tr><td>Read standings while people are still out</td><td><a href="#the-results-view">The Results view</a></td></tr><tr><td>Show the crowd how many are still out</td><td><a href="#the-public-screens">Spectator, kiosk and arena screens</a></td></tr><tr><td>Ask a question in plain language</td><td><a href="#asking-an-ai-assistant">An AI assistant</a></td></tr><tr><td><em>Prove</em> who came back, not just what Manager believes</td><td><a href="#the-cross-check-that-isnt-a-screen">Station memory</a></td></tr></tbody></table><h2 id="the-dashboard-competitors-tile" tabindex="-1">The dashboard Competitors tile <a class="header-anchor" href="#the-dashboard-competitors-tile" aria-label="Permalink to &quot;The dashboard Competitors tile&quot;">​</a></h2><p>The headline number, and where most people start. The <strong>Competitors</strong> tile on the <a href="./dashboard">event dashboard</a> carries the running totals for the race, with a graph of how many people have been on course through the day beneath them.</p><p><img src="'+t+'" alt="The dashboard Competitors tile: Total 148, Started 104, On course 5 and Pending 3 shown as raised buttons, Finished 99, above a curve of how many competitors were on course over the day."></p><p>Three of those numbers are <strong>buttons</strong>: <strong>Not started</strong>, <strong>On course</strong> and <strong>Pending</strong> are drawn as coloured, raised buttons whenever they have anything to show. Click any of them to open the list behind it. (At zero there is nothing to open, so they&#39;re drawn like the plain counts around them — no colour, no button.)</p><ul><li><strong>Not started</strong> — everyone who has not started. The complement of <strong>Started</strong>, so the two always add up to <strong>Total</strong>. It&#39;s the one count that gives way on a narrow tile: the counts never wrap to a second line, so once there isn&#39;t room to write its label in full, this is the one that goes. Widen the tile to bring it back.</li><li><strong>On course</strong> — everyone Manager believes is still out, including anyone who <strong>checked in</strong> and hasn&#39;t come back. This is the safety number, and the one you want at zero at the end of the day.</li><li><strong>Pending</strong> — runners who crossed a <strong>radio finish</strong> but have not downloaded their card. They are <em>back</em> — they just have no confirmed result yet.</li></ul><p>The count includes <strong>cards no entry accounts for</strong>: radio activity from a card, with no finish punch, that nobody entered in the event can still be out on. Somebody is out there, so they are counted. That is a card matching no competitor at all — and also a competitor <strong>out on a second course</strong>, whose first run has finished and downloaded and so cannot be out on this one. See <a href="#more-than-one-run-on-a-card">More than one run on a card</a>.</p><h2 id="the-on-course-dialog" tabindex="-1">The On course dialog <a class="header-anchor" href="#the-on-course-dialog" aria-label="Permalink to &quot;The On course dialog&quot;">​</a></h2><p>Click <strong>On course</strong> on the tile. This is the single most useful screen for a safety check — everyone still out, on one list.</p><p><img src="'+o+'" alt="The On course dialog listing five competitors still out, each with name, card number, class, start time and a Last seen control with time — controls 31, 32 and 33, and one row reading START. The last row is an unknown card."></p><p>Each row gives you:</p><ul><li><strong>Name</strong> — click it to open that competitor. A card no entry accounts for shows in italics: <em>Unknown</em> where nobody in the event carries it, or the runner&#39;s name and which run this is (<em>Jordan Blake, run 2</em>) where somebody does. Clicking either offers to register the card as a competitor. A <strong>Checked in</strong> tag marks a runner who punched the check but has no start — see <a href="#what-the-counts-include">What the counts include</a>.</li><li><strong>Card number</strong>, <strong>Class</strong> and <strong>Start</strong> time.</li><li><strong>Elapsed</strong> — how long they have been out, counting up every second while the dialog is open. It runs from their start time, so it is what their race time will be if they come in now. Unknown cards count from their <strong>start punch</strong>; a card first seen at a control, with no start punch behind it, shows <code>--:--</code> rather than guess.</li><li><strong>Last seen</strong> — the last thing that saw them and when: a radio control they punched (<code>31 @ 11:03:18</code>), <code>START</code> where they have punched nothing since starting, the check they punched over the radio, or the <strong>Start station</strong> or <strong>Check station</strong> whose memory you have read. A runner who checked in has been seen, so they always show where. <code>-</code> means nothing has seen them at all. The chip carries the control&#39;s code, or the radio&#39;s name if you named it.</li></ul><p>The list sorts <strong>longest-unseen first</strong>, so the names that most deserve a look are at the top. That is <em>last seen</em>, not <em>started</em>: in the example above Jordan Blake heads the list on an 11:03 punch at control 31, above three people who started after him but have been seen more recently. Click <strong>Elapsed</strong> to sort by that instead, shortest time on course first — click again for longest-out first, which is the other way to read the same list when you are asking who has been out too long rather than who has been unseen too long. Every row also carries a <strong>delete radio punches</strong> action for the rare case where a spurious punch is what is holding a card on the list — see <a href="./resolving-issues">Resolving issues on the day</a>.</p><blockquote><p><strong><code>--:--</code> means Manager cannot say, not zero.</strong> The clock it counts to is the <em>event</em> clock, so <strong>Elapsed</strong> is blank for everyone once the event is no longer running, and blank for anyone with no start time — a runner whose start Manager never recorded has no elapsed to show, however long they have been out. Their name is still on the list; that is the part that matters for the safety check.</p></blockquote><h2 id="the-pending-dialog" tabindex="-1">The Pending dialog <a class="header-anchor" href="#the-pending-dialog" aria-label="Permalink to &quot;The Pending dialog&quot;">​</a></h2><p>Click <strong>Pending</strong> on the tile. These runners have a radio finish punch and nothing since.</p><p><img src="'+h+'" alt="The Pending dialog: three competitors with name, card number, class and the radio finish control and time that made their result preliminary."></p><p>They are <strong>not</strong> a safety problem — the finish punch is proof they are back — but they are unfinished business: their result is still <em>provisional</em> (<code>OK*</code>) and will never be published as a result until the card is read. This is the list the download tent chases. See <a href="./safety-check#ok-but-not-downloaded-provisional-ok">provisional OK</a> for what that status does and doesn&#39;t mean.</p><h2 id="the-pending-downloads-tile" tabindex="-1">The Pending downloads tile <a class="header-anchor" href="#the-pending-downloads-tile" aria-label="Permalink to &quot;The Pending downloads tile&quot;">​</a></h2><p>The same chase-up list, kept in the corner of your eye rather than opened. <strong>Pending downloads</strong> is a <a href="./dashboard">dashboard tile</a> you switch on yourself (<strong>Edit dashboard → Add tile</strong>), showing as many names as fit: the <strong>time</strong> the radio put each of them across the line, their <strong>name</strong>, and how long they have been <strong>waiting</strong> since.</p><p>Longest wait at the top, so the name that has been owed the longest is the one you see first. Click a row to open that competitor&#39;s record — except a card with no entry behind it, which has nobody to open and is drawn as a plain row. Enter somebody against it from the <a href="#the-pending-dialog">Pending dialog</a>, which offers that.</p><p>Cards no entry accounts for are on this list too, by their number (<em>Unknown card 8536559</em>) or by the runner and run (<em>Jordan Blake, run 2</em>). A card the radio saw finish that nobody has read is exactly what this list is for, whether or not there is an entry to put a name to it.</p><h2 id="the-not-started-dialog" tabindex="-1">The Not started dialog <a class="header-anchor" href="#the-not-started-dialog" aria-label="Permalink to &quot;The Not started dialog&quot;">​</a></h2><p>Click <strong>Not started</strong> on the tile. This is the other half of the field: everyone who has not gone out, with their name, card number, class, start time and status. Earliest start time first, so anybody already overdue at the start lane is at the top; anyone with no start time at all sorts to the bottom, because they cannot be overdue.</p><p>The list is deliberately wider than &quot;still expected&quot;, and the <strong>Status</strong> column is what tells the two apart:</p><ul><li><strong>No status</strong> — nobody has accounted for this person yet. Before their start time they are simply still to come; well after it, they are a no-show you have not cleared.</li><li><strong>DNS</strong>, <strong>Not competing</strong> or <strong>Cancelled</strong> — the absence has already been dealt with, by you or by a <a href="./safety-check#course-closure-settling-the-list-at-a-set-time">course closure</a>.</li></ul><p>Marking a no-show <strong>DNS</strong> therefore does not change the count — it moves a name from the first group to the second, which is the point: the tile never quietly loses an entry, and <strong>Started</strong> plus <strong>Not started</strong> always equals <strong>Total</strong>. Click a name to open that competitor.</p><p>For the end-of-day procedure this feeds, including the bulk <strong>Set competitors DNS</strong> action, see <a href="./safety-check#marking-no-shows-as-dns-bulk">Marking no-shows as DNS</a>.</p><h2 id="the-competitor-list" tabindex="-1">The competitor list <a class="header-anchor" href="#the-competitor-list" aria-label="Permalink to &quot;The competitor list&quot;">​</a></h2><p>The dialogs are read-mostly; the <a href="./../event-setup/competitors-clubs-teams">competitor list</a> is where you can search, sort, filter and edit. Set the <strong>Status</strong> filter to <strong>On course</strong>:</p><p><img src="'+l+'" alt="The competitor list with the Status filter set to On course: five competitors, each showing a Last seen chip naming the control and time — Spectator, Arena, or START for two who have not been seen since the start."></p><p>Worth knowing:</p><ul><li>The <strong>On course</strong> option is always in the filter, even before anyone is on course, so you can pre-set it.</li><li>It names the same people the dashboard&#39;s <strong>On course</strong> count counts. So it includes runners who <strong>checked in</strong> and haven&#39;t come back, and <strong>Overtime</strong> runners nobody has seen come back; and it leaves out relay runners still waiting in the changeover pen who haven&#39;t checked in. Where the check-in is the only reason somebody is listed — their status is blank, or they&#39;re a relay runner still in the pen — they carry a <strong>Checked in</strong> tag in the <strong>Status</strong> column.</li><li>The <strong>Last seen</strong> column shows what last saw each runner on the list inline — a radio punch, the check included, or a Start or Check station&#39;s memory — a fast way to spot the people nobody has seen since the start (the two <code>START</code> rows above).</li><li>The same filter offers <strong>OK (not downloaded)</strong> — the same set as the Pending dialog, but in a list you can act on.</li></ul><h2 id="the-class-list" tabindex="-1">The class list <a class="header-anchor" href="#the-class-list" aria-label="Permalink to &quot;The class list&quot;">​</a></h2><p>The <strong>Classes</strong> page has an <strong>On course</strong> column: how many are still out, class by class.</p><p><img src="'+c+'" alt="The class list with an On course column showing a count against each of the five classes."></p><p>This is the one to use when the question is about the <em>courses</em> rather than the people — most often &quot;can we start collecting controls yet?&quot;. A class showing zero has nobody left who could still punch its controls.</p><p><strong>Click the count</strong> to open the <a href="#the-on-course-dialog">On course dialog</a> for that class alone — the same list, same columns, narrowed to the one class. A class with nobody out shows a green <strong>None</strong> chip instead, and there is nothing to open.</p><blockquote><p><strong>Note:</strong> The per-class list cannot show <strong>unknown cards</strong>, because an unmatched card belongs to no class. For the safety check use the dashboard&#39;s own On course dialog, which has them.</p></blockquote><blockquote><p><strong>Note:</strong> The column counts runners who <strong>checked in</strong> and haven&#39;t come back, like the dashboard does. The spectator class list doesn&#39;t, so the two can differ by exactly those runners.</p></blockquote><blockquote><p><strong>Note:</strong> In a relay, the mass start technically puts every leg of a class out at the gun. This column counts who is <em>genuinely</em> running, so the runners still standing in the changeover pen are not counted — unless they&#39;ve <strong>checked in</strong>, which keeps them on every one of your own lists until they&#39;re back.</p></blockquote><h2 id="the-results-view" tabindex="-1">The Results view <a class="header-anchor" href="#the-results-view" aria-label="Permalink to &quot;The Results view&quot;">​</a></h2><p>The <a href="./../after-the-event/results">Results view</a> is built around finishers, but it will tell you about the people still out:</p><ul><li>The per-class <strong>summary</strong> carries an <strong>On course</strong> column, so you can see which classes are still incomplete.</li><li><strong>Include → On course competitors</strong> adds them to the tables themselves, for a provisional standing with the field still out.</li></ul><p>Anything you read there while the on-course count is above zero is provisional by definition — and an exported or published result file leaves the unfinished runners out of the rankings whatever this view is set to.</p><h2 id="the-public-screens" tabindex="-1">The public screens <a class="header-anchor" href="#the-public-screens" aria-label="Permalink to &quot;The public screens&quot;">​</a></h2><p>The screens the crowd sees carry the same picture, in a coarser form:</p><ul><li><p><strong>Spectator and kiosk class lists</strong> show an &quot;<em>N</em> on course&quot; badge per class, next to how many have finished.</p><p><img src="'+d+'" alt="The spectator live-results class list on a phone: each class card shows a competitor count and badges reading &quot;1 on course&quot; and &quot;5 finished&quot;."></p></li><li><p><strong>Leaderboard and Commentary</strong> screens show on-course runners in the class tables — with a projected time and position where a radio split allows one, and <strong>On course</strong> in place of a time where it doesn&#39;t. See <a href="./../screens/tv-screens">TV screens</a> and <a href="./../screens/commentary">Commentary</a>.</p></li></ul><p>None of them count a runner who has only <strong>checked in</strong>. Reaching the check is not starting, so to the crowd that runner is still waiting to start, and the commentary feed doesn&#39;t announce them as a starter until they actually go. In a relay, the crowd sees a runner go out at the mass start (leg 1) or when the previous leg comes back — never at the check.</p><p>Once a <a href="./safety-check#course-closure-settling-the-list-at-a-set-time">course closure</a> passes, though, a checked-in runner nobody has seen come back is marked <strong>Overtime</strong>, and from then on the spectator class lists&#39; &quot;on course&quot; badges count them too, as they count any Overtime runner nobody has seen come back: at that point they are somebody the event cannot account for, not somebody waiting to start.</p><h2 id="the-pending-downloads-info-screen" tabindex="-1">The Pending downloads info screen <a class="header-anchor" href="#the-pending-downloads-info-screen" aria-label="Permalink to &quot;The Pending downloads info screen&quot;">​</a></h2><p>The <a href="./../screens/info-screens">info screens</a> include <strong>Pending downloads</strong> — the same names as <a href="#the-pending-downloads-tile">the dashboard tile</a>, sized to be read across a tent.</p><p><img src="'+n+'" alt="The Pending downloads info screen: large cards, each carrying a competitor&#39;s name and a &quot;to download&quot; badge."></p><p>Prop it up at the download tent and it chases the cards for you: the names sit there, longest-overdue first, until the card is read. Deliberately, runners still <strong>on course</strong> are <em>not</em> on it — they are a different problem, and putting them on the same screen would bury the two or three names the tent is actually chasing.</p><p>Like the tile, it carries cards no entry accounts for — by number, or by the runner and which run it is.</p><p>The <strong>Radio control</strong> info screen answers the neighbouring question — who has just come past a chosen radio control — which is how you see the field still moving through a spectator control or a changeover.</p><h2 id="asking-an-ai-assistant" tabindex="-1">Asking an AI assistant <a class="header-anchor" href="#asking-an-ai-assistant" aria-label="Permalink to &quot;Asking an AI assistant&quot;">​</a></h2><p>If you have <a href="./../reference/ai-assistants-mcp">AI assistants</a> switched on, &quot;who is still out on course in M21E?&quot; is a question you can simply ask, and the assistant reads the same data these screens do. It is the fastest way to slice the question in a way no screen offers (&quot;who is still out from Bushflyers?&quot;), and it can read the radio punches behind each answer.</p><p>Two things to hold on to when you do:</p><ul><li>An assistant reads what Manager knows. It is no better informed about the forest than the <strong>On course</strong> list is.</li><li>Results it quotes while anyone is still out are provisional; the tools tell it so, and a good assistant will say so back.</li></ul><h2 id="the-cross-check-that-isn-t-a-screen" tabindex="-1">The cross-check that isn&#39;t a screen <a class="header-anchor" href="#the-cross-check-that-isn-t-a-screen" aria-label="Permalink to &quot;The cross-check that isn&#39;t a screen&quot;">​</a></h2><p>Every screen on this page is Manager&#39;s <em>belief</em>, built from start times, radio punches and downloads. When you need proof, read the units themselves with <a href="./station-memory">Station Memory</a>:</p><ul><li>the <strong>finish</strong> unit&#39;s memory says who actually punched the finish — anyone in it is out of the forest;</li><li>the <strong>start</strong> unit says who actually went out, which is what separates a genuine missing runner from a no-show who never turned up;</li><li>the <strong>check</strong> unit says who reached the check — present at the start area, not necessarily out on the course. Reading it checks those runners in, which puts them on your own on-course lists until something says they&#39;re back.</li></ul><p>Applying those records also <em>moves</em> people in and out of the on-course count, which is why reading the finish station is the strongest single tool for clearing the list at the end of the day. Note that contactless (SIAC &quot;air&quot;) punches are never recorded in a station&#39;s memory.</p><h2 id="what-the-counts-include" tabindex="-1">What the counts include <a class="header-anchor" href="#what-the-counts-include" aria-label="Permalink to &quot;What the counts include&quot;">​</a></h2><p>Four quirks are worth knowing before you read too much into a number:</p><ul><li><strong>Overtime does not empty the list.</strong> If your event declares a <a href="./safety-check#course-closure-settling-the-list-at-a-set-time">course closure</a>, everyone still out at that time of day is marked <strong>Overtime</strong> — but that is a statement about their <em>result</em>, not a sighting, so they stay in every count and list on this page until something says they are back: a race time, a radio finish punch, a downloaded card, or a finish station read. Emptying these screens on the clock is exactly what you would not want them to do. <strong>The same applies to an Overtime you set by hand</strong> — it is a call about a placing, not a sighting. (And the same goes for the Pending list: the <code>OK*</code> runners the closure moved to <strong>DNF</strong> are still on it, still waiting for their card to be read.)</li><li><strong>No-shows are counted.</strong> Anyone whose allocated start time has passed is flagged on course, even with no start punch — so the list normally includes every entrant who never turned up. Clearing them (<strong>Set competitors DNS</strong>) is what makes the rest meaningful. See <a href="./safety-check#marking-no-shows-as-dns-bulk">Marking no-shows as DNS</a>.</li><li><strong>Checked-in runners are counted.</strong> A check punch — by radio, or read from the check station&#39;s memory — does not start anybody: their status stays blank, and nothing public shows them as out. But somebody who checks in and then never punches the start may be out there, so Manager counts them in the tile, the On course dialog, the competitor list&#39;s <strong>On course</strong> filter and the class list&#39;s column until a radio finish, a card download, a finish station read or a status you set says otherwise. The same goes for a relay runner who has checked in while still waiting in the changeover pen. The <strong>Checked in</strong> tag appears only while the check-in is the only reason they&#39;re listed — once they&#39;re out on course by any other measure, the tag would tell you nothing. At <a href="./safety-check#course-closure-settling-the-list-at-a-set-time">course closure</a> they become <strong>Overtime</strong>, not DNS, so they stay on the list (and from then on the tag goes, since Overtime keeps them there in its own right); the bulk <strong>Set competitors DNS</strong> leaves them out. Mark them <strong>DNS</strong> yourself once you know they didn&#39;t go.</li><li><strong>Cards no entry accounts for are counted</strong> in the tile and the On course dialog — an unidentified card out on the course is still somebody out on the course, and so is a competitor out on a second run.</li></ul><h2 id="more-than-one-run-on-a-card" tabindex="-1">More than one run on a card <a class="header-anchor" href="#more-than-one-run-on-a-card" aria-label="Permalink to &quot;More than one run on a card&quot;">​</a></h2><p>At a local event or a schools day, a competitor may run more than one course on the same card. They finish the first, download, and their result is final — then they clear, check, and go through the start again.</p><p>Manager cannot put that second run on their entry: the entry is a completed result, and a second run must not overwrite it. What it does instead is show the run <strong>as a card nothing accounts for</strong>, on the same rows it uses for a card nobody is entered against — named from the entry where it can be, and labelled with which run it is (<em>Jordan Blake, run 2</em>). So the runner is on the <strong>On course</strong> list while they are out, and on the <strong>Pending</strong> lists when the radio sees them finish, exactly like anybody else. When they download, the card is offered to you as a reused card, with its owner ready to duplicate for the second run — which is what closes the row.</p><p>Three things worth knowing:</p><ul><li><strong>A card somebody is still to go out on is not this.</strong> Where a family shares one stick between courses, the sibling who has not run yet is the one a fresh start punch belongs to, and they appear on the On course list under their own name in the ordinary way. A run is only treated as unaccounted-for once every entry on the card has finished.</li><li><strong>The second run needs the start or check unit on the radio.</strong> That is how Manager tells a runner who has gone round again from a stray read after everybody is home. Without a radioed start or check box, a repeat run is not picked up until the card is downloaded.</li><li><strong>Entering the second run in advance is still the tidier way to run it.</strong> A competitor entered in both classes has two entries, and the second behaves like any other entry from the moment they start. The behaviour on this page is what covers you when nobody got round to it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./safety-check">Safety check: accounting for everyone</a> — the end-of-day procedure</li><li><a href="./dashboard">The event dashboard</a> — the Competitors tile in context</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — what puts a competitor in each status</li><li><a href="./station-memory">Station Memory</a> — reading a unit&#39;s own punch backup</li><li><a href="./../screens/info-screens">Event info screens</a> — the Pending downloads and Radio control screens</li><li><a href="./radio-punches">Radio punches</a> — the punches these views are built from</li><li><a href="./resolving-issues">Resolving issues on the day</a> — fixing a wrong picture</li></ul>',80)])])}const q=s(u,[["render",g]]);export{T as __pageData,q as default};
